const tweets = $input.all().map(item => {
  const likeCount = item.json.likeCount || 0;
  const viewCount = item.json.viewCount || 1; // Avoid division by zero

  return {
    twitterUrl: item.json.twitterUrl,
    text: item.json.text,
    likeViewRate: likeCount / viewCount
  };
});

return [
  {
    json: {
      tweets
    }
  }
];

const threads = $input.item.json.output.threads;

// Map each thread object into its own item
const result = threads.map(thread => {
  return { json: thread };
});

return result;

